-- Modify "broadcasts" table
ALTER TABLE "public"."broadcasts" ADD COLUMN "body_format" character varying NOT NULL DEFAULT 'html';
-- Create "email_templates" table
CREATE TABLE "public"."email_templates" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  "subject" character varying NOT NULL DEFAULT '',
  "body_html" character varying NOT NULL DEFAULT '',
  "body_format" character varying NOT NULL DEFAULT 'html',
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "email_templates_workspaces_email_templates" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "emailtemplate_workspace_id" to table: "email_templates"
CREATE INDEX "emailtemplate_workspace_id" ON "public"."email_templates" ("workspace_id");
